 36	    private function configureDatabase(): void
 37	    {
 38	        $port = 0;
 39	
 40	        if (defined('APP_DB_TESTS_PORT')) {
 41	            $port = (int)APP_DB_TESTS_PORT;
 42	        }
 43	
 44	        DBHelper::registerDB(
 45	            'tests',
 46	            APP_DB_TESTS_NAME,
 47	            APP_DB_TESTS_USER,
 48	            APP_DB_TESTS_PASSWORD,
 49	            APP_DB_TESTS_HOST,
 50	            $port
 51	        );
 52	
 53	        DBHelper::selectDB('tests');
 54	    }
 55	
 56	    private function configureUsers(): void
 57	    {
 58	        $users = AppFactory::createUsers();
 59	        $missingIDs = array();
 60	
 61	        foreach(Application::getSystemUserIDs() as $id)
 62	        {
 63	            if(!$users->idExists($id))
 64	            {
 65	                $missingIDs[] = $id;
 66	            }
 67	        }
 68	
 69	        if(!empty($missingIDs))
 70	        {
 71	            throw new BootException(
 72	                'Test database not seeded: system user(s) missing.',
 73	                sprintf(
 74	                    'The following system user IDs are missing from the test database: [%s]. '.
 75	                    'Run "composer seed-tests" to initialize the test environment.',
 76	                    implode(', ', $missingIDs)
 77	                ),
 78	                self::ERROR_TEST_DB_NOT_SEEDED
 79	            );
 80	        }
 81	
 82	        $this->log('System users verified.');
 83	    }
 84	
 85	    public static function seedSystemUsers(): void
 86	    {
 87	        DBHelper::startTransaction();
 88	
 89	        try
 90	        {
 91	            Application::createInstaller()
 92	                ->getTaskByID('InitSystemUsers')
 93	                ->process();
 94	
 95	            DBHelper::commitTransaction();
 96	        }
 97	        catch(\Throwable $e)
 98	        {
 99	            DBHelper::rollbackConditional();
100	            throw $e;

101	        }
102	    }
